'use client'

import { Textmoji, type StaticEmojiSource } from '@/components/spaceui/textmoji'

export interface TextmojiDemoProps {
  text?: string
  source?: StaticEmojiSource
}

export default function Demo({
  text = 'Ship your ideas faster 🚀 with Space UI 🫧🦄',
  source = 'fluent',
}: TextmojiDemoProps) {
  return (
    <div className="flex w-full max-w-md flex-col gap-4 px-6 text-center">
      <p className="text-lg leading-relaxed text-foreground">
        <Textmoji source={source}>{text}</Textmoji>
      </p>
    </div>
  )
}
